questionvariables.text:
/*Defining the question*/
lower:rand(9)+1;/*random number for the lower limit*/
upper:(lower +1);/*random number for the upper limit*/
coeff_x:rand_with_prohib(-8,8,[0]);/*random number for the coefficient of x in the numerator*/
constant:rand(9)+1;/*random number for the constant of the denominator*/
power:rand(2)+2;/*random value of n outside the root sign*/
f_x:ev((constant/(coeff_x*x - constant)^(power)), simp);/*the function*/
part_frac_f_x:partfrac(f_x,x);
num_part:num(part_frac_f_x);
den_part:denom(part_frac_f_x);
func_1:coeff_x*x -constant;
fx_1:factor(func_1);



/*Defining the question*/
lower:rand(9)+1;/*random number for the lower limit*/
upper:(lower +1);/*random number for the upper limit*/
coeff_x:rand_with_prohib(-8,8,[0]);/*random number for the coefficient of x in the numerator*/
constant:rand(9)+1;/*random number for the constant of the denominator*/
power:rand(2)+2;/*random value of n outside the root sign*/
f_x:ev((constant/(coeff_x*x - constant)^(power)), simp);/*the function*/
part_frac_f_x:partfrac(f_x,x);
num_part:num(part_frac_f_x);
den_part:denom(part_frac_f_x);
func_1:coeff_x*x -constant;
fx_1:factor(func_1);






/*Substitution and other tasks*/
us:ev((coeff_x*x - constant), simp);

diff_u:diff(us,x);
func_2:diff_u*(u^(-power+1)/(-power+1))
subst_u:subst(us,u,func_2);
den_subst:denom(subst_u);

u_lower: ev(us, x=lower);
u_upper:ev(us, x=upper);
g_u:ev((1/diff_u)*(constant/(u^power)), simp);/*the function*/

/*Evaluating lower and upper bounds as follow*/
lower_u: at(us,[x=lower]);
upper_u: at(us,[x=upper]);

/*Model answers*/
ta_g:integrate(g_u,u);
upper_value:subst(u_upper,x,ta_g);
lower_value:subst(u_lower,x,ta_g);
eval_ta_g: ev(ta_g,u=us);
ta_1:integrate(f_x,x,lower,upper);

/*Worked solution*/
eval_expr1: constant/(diff_u*u^power);
expr2: integrate(eval_expr1,u);

